  return {...verified, discovery, ...(engine ? {engine} : {}), ...(authorization ? {local_authorization: authorization} : {}),
    ...(controls ? {local_controls: true} : {}), previous, technical,
    local_author: author, local_artifact: artifact, local_receipt: bundle};
